from django.shortcuts import render
from django.http import HttpResponse, JsonResponse
from .models import DinnerParty

def dinner_party(request):
    party = DinnerParty.objects.get(pk=1)
    guests = party.guests

    context = {
        'party': party,
        'guests': guests
    }

    return render(request, 'dinner_party.html', context)
